function showToast(message){const t=$("#toast");t.textContent=message;t.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove("show"),2800)}
function setRole(role){currentRole=role;$$(".role-option").forEach(b=>b.classList.toggle("active",b.dataset.role===role));$("#email").value=demo[role].email;$("#password").value=demo[role].password;$("#loginError").textContent=""}
function login(){
  const email=$("#email").value.trim(),password=$("#password").value;
  const match=Object.entries(demo).find(([role,d])=>role===currentRole&&d.email===email&&d.password===password);
  if(!match){$("#loginError").textContent="Those demo details don’t match. Try the sample credentials below.";return}
  currentRole=match[0];currentPage="overview";$("#loginScreen").classList.add("hidden");$("#portal").classList.remove("hidden");
  const user=demo[currentRole];$("#sidebarName").textContent=user.name;$("#sidebarYear").textContent=user.year;$("#sidebarAvatar").textContent=user.initials;$("#topAvatar").textContent=user.initials;$("#topName").textContent=user.name;$("#topRole").textContent=user.roleLabel;$("#rolePill").textContent=currentRole==="student"?"STUDENT PORTAL":"ADMIN PORTAL";
  renderNav();renderPage();window.scrollTo(0,0);
}
function logout(){ $("#portal").classList.add("hidden");$("#loginScreen").classList.remove("hidden");$("#sidebar").classList.remove("open");$("#mobileOverlay").classList.remove("show");setRole("student");showToast("You’ve been logged out."); }
function renderNav(){
 const nav=currentRole==="student"?studentNav:adminNav;
 $("#sideNav").innerHTML=nav.map(section=>`<div class="nav-section-label">${section.section}</div>${section.items.map(item=>`<button class="nav-item ${item[0]===currentPage?"active":""}" data-page="${item[0]}"><span class="nav-icon">${item[1]}</span><span>${item[2]}</span>${item[3]?.count?`<span class="nav-count">${item[3].count}</span>`:""}</button>`).join("")}`).join("");
}
function goPage(page){
 if(currentRole==="student" && ["students","classes","resources","assign","submissions"].includes(page)) return;
 if(currentRole==="admin" && ["subjects","notes","worksheets","schedule","account"].includes(page)) {
   if(page==="account"){currentPage="account";} else {showToast("This section is available from the student view in this prototype.");return}
 }
 currentPage=page;renderNav();renderPage();$("#sidebar").classList.remove("open");$("#mobileOverlay").classList.remove("show");window.scrollTo({top:0,behavior:"smooth"});
}
function heading(title,subtitle,actions=""){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function panel(title,subtitle,body,action=""){return `<section class="panel"><div class="panel-header"><div><div class="panel-title">${title}</div>${subtitle?`<div class="panel-subtitle">${subtitle}</div>`:""}</div>${action}</div><div class="panel-body">${body}</div></section>`}
function stat(icon,value,label,foot,tone=""){return `<div class="stat-card"><div class="stat-top"><span class="stat-icon ${tone}">${icon}</span><span class="stat-trend">↗ On track</span></div><div class="stat-value">${value}</div><div class="stat-label">${label}</div><div class="stat-foot">${foot}</div></div>`}
function chartSvg(){
 const months=["May","Jun","Jul","Aug","Sep","Oct"];
 const series=[
  {name:"Methods",color:"#1769e0",v:[48,54,52,66,70,78]},
  {name:"Physics",color:"#ff3f96",v:[44,48,58,55,64,69]},
  {name:"Chemistry",color:"#111318",v:[58,62,66,72,77,84]},
  {name:"Applications",color:"#7f9fe0",v:[51,57,55,62,68,73]}
 ];
 const x=i=>44+i* (520/5), y=v=>155-(v-30)*2.0;
 let grid=[40,50,60,70,80,90].map(v=>`<line x1="38" y1="${y(v)}" x2="575" y2="${y(v)}" stroke="#edf0f5" stroke-width="1"/><text x="27" y="${y(v)+3}" fill="#a0a4ad" font-size="9" text-anchor="end">${v}</text>`).join("");
 let lines=series.map(s=>`<polyline points="${s.v.map((v,i)=>`${x(i)},${y(v)}`).join(" ")}" fill="none" stroke="${s.color}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>${s.v.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="#fff" stroke="${s.color}" stroke-width="2"/>`).join("")}`).join("");
 let labels=months.map((m,i)=>`<text x="${x(i)}" y="176" fill="#969ba7" font-size="10" text-anchor="middle">${m}</text>`).join("");
 return `<svg class="progress-chart" viewBox="0 0 600 190" role="img" aria-label="Illustrative multi-subject progress line chart from May to October"><rect x="0" y="0" width="600" height="190" fill="#fff"/>${grid}${lines}${labels}</svg>`;
}
function legend(){return `<div class="chart-legend"><span class="legend-item"><i class="legend-dot" style="background:#1769e0"></i>Methods</span><span class="legend-item"><i class="legend-dot" style="background:#ff3f96"></i>Physics</span><span class="legend-item"><i class="legend-dot" style="background:#111318"></i>Chemistry</span><span class="legend-item"><i class="legend-dot" style="background:#7f9fe0"></i>Applications</span></div>`}
function taskRows(list=assignments.slice(0,3)){
 return `<div class="task-list">${list.map(a=>`<div class="task-row"><div class="task-symbol ${a.tone==="pink"?"pink":""}">${a.type==="Quiz"?"✎":"▤"}</div><div class="task-copy"><strong>${a.title}</strong><small>${a.subject} · Due ${a.due}</small></div><span class="status ${a.status==="Submitted"?"black":a.tone}">${a.status}</span></div>`).join("")}</div>`;
}
function subjectCards(){return `<div class="subject-grid">${subjects.map(s=>`<article class="subject-card" data-action="subject" data-subject="${s.name}"><div class="subject-top"><div class="subject-symbol ${s.color==="pink"?"pink":""}">${s.icon}</div><span class="status ${s.color}">${s.progress}%</span></div><h3>${s.name}</h3><p>${s.topic}</p><div class="subject-progress-label"><span>Overall progress</span><strong>${s.progress}%</strong></div><div class="progress-track"><div class="progress-fill ${s.color==="pink"?"pink":""}" style="width:${s.progress}%"></div></div></article>`).join("")}</div>`}
function resourceRows(list=resources){return `<div class="resource-list">${list.map((r,i)=>`<div class="resource-row"><div class="file-icon ${r.color==="blue"?"blue":""}">${r.type}</div><div class="resource-info"><strong>${r.title}</strong><small>${r.subject} · ${r.size} · ${r.date}</small></div><div class="resource-actions"><button class="btn btn-sm" data-download="${i}">↓ Download</button></div></div>`).join("")}</div>`}
function renderStudentOverview(){
 return `${heading("Hey Alex, ready to make progress? 👋","Here’s your learning snapshot. Small, consistent steps add up.",`<button class="btn" data-page="notes">Browse resources</button><button class="btn btn-primary" data-page="worksheets">View my work <span>→</span></button>`)}
 <div class="notice-banner"><span class="notice-symbol">✦</span><div><strong>You’re building a great study rhythm.</strong><p>You’ve completed 8 learning tasks this month. Keep the momentum going and tackle your next worksheet.</p></div><button class="dismiss" data-dismiss>×</button></div>
 <div class="stats-grid">${stat("↗","76%","Average performance","<strong>+8%</strong> compared with last month")}${stat("✓","8 / 10","Tasks completed","<strong>2 tasks</strong> still need your attention","pink")}${stat("◷","6.5 hrs","Study time this week","Across all your subjects")}${stat("✦","4","Subjects enrolled","Year 12 ATAR programme","pink")}</div>
 <div class="dashboard-grid"><div class="section-stack">${panel("Your progress","Performance over the last 6 months",`<div class="filter-row" style="margin-bottom:5px"><div>${legend()}</div><select class="chart-period" id="chartPeriod"><option>Last 6 months</option><option>Last 3 months</option></select></div><div class="chart-wrap">${chartSvg()}</div><div class="chart-note"><span class="note-icon">↗</span><span><strong>Good momentum!</strong> Chemistry has improved consistently. Physics dipped slightly in August, but has recovered since.</span></div>`)}
 ${panel("Your subjects","Pick up where you left off",subjectCards(),`<button class="link-btn" data-page="subjects">View all →</button>`)}</div>
 <div class="section-stack">${panel("Coming up","Your next deadlines",taskRows(),`<button class="link-btn" data-page="worksheets">View all →</button>`)}
 ${panel("Recently added","Fresh resources from your tutors",resourceRows(resources.slice(0,3)),`<button class="link-btn" data-page="notes">View library →</button>`)}
 ${panel("A little reminder","Your next step",`<div class="announcement"><div class="task-symbol pink">✦</div><div><strong>Focus beats cramming.</strong><p>Try 25 minutes of focused practice, then take a 5-minute break. You’ve got this.</p><small>STUDY TIP · ETP TEAM</small></div></div>`)}</div></div>`;
}
