function submissionTable(list){return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Submission</th><th>Status</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="table-person"><div class="avatar">${s.initials}</div><div><strong>${s.student}</strong><small>${s.submitted}</small></div></div></td><td><strong>${s.work}</strong><div style="font-size:9px;color:#8b909b;margin-top:4px">${s.subject}</div></td><td><span class="status ${s.status==="Reviewed"?"blue":"pink"}">${s.status}</span></td><td><button class="link-btn" data-action="review" data-student="${s.student}">Open</button></td></tr>`).join("")}</tbody></table></div>`}
function renderSubjects(){return `${heading("My subjects","Everything you’re studying, organised in one place.")}<div class="stats-grid">${stat("▤","4","Enrolled subjects","Your Year 12 ATAR programme")}${stat("✓","76%","Average progress","Across your subjects","pink")}${stat("◷","3","Upcoming tasks","Due in the next 7 days")}${stat("✦","12","Resources added","This term","pink")}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Your subject spaces</div><div class="panel-subtitle">Choose a subject to see notes, worksheets, and assessment activity.</div></div></div><div class="panel-body">${subjectCards()}</div></div>`}
function renderNotes(){return `${heading("Notes & resources","Your tutor’s notes, revision guides, formula sheets, and study materials.",`<button class="btn" data-action="filter-resources">Filter resources</button>`)}<div class="panel"><div class="panel-header"><div><div class="panel-title">Resource library</div><div class="panel-subtitle">Recently shared learning materials for your subjects.</div></div><span class="status blue">12 resources</span></div><div class="panel-body"><div class="filter-row"><input class="search-input" id="resourceSearch" placeholder="Search notes and resources…"><div class="filter-group"><select class="select-input" id="resourceSubject"><option value="">All subjects</option>${subjects.map(s=>`<option>${s.name}</option>`).join("")}</select><select class="select-input"><option>Newest first</option><option>Oldest first</option></select></div></div><div id="resourceRows">${resourceRows()}</div></div></div>`}
function renderWorksheets(){return `${heading("Worksheets","Practice makes progress. Find your tasks, download the sheets, and submit your answers.",`<button class="btn" data-page="notes">Browse resources</button>`)}<div class="stats-grid">${stat("▤","2","To do","Your next steps","pink")}${stat("◷","1","In progress","Keep going")}${stat("✓","1","Submitted","Awaiting or completed review","pink")}${stat("✦","76%","Average score","On your submitted work")}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">My worksheets</div><div class="panel-subtitle">Download the worksheet, complete it, then upload your answers for feedback.</div></div></div><div class="panel-body">${taskRows(assignments.filter(a=>a.type==="Worksheet"))}<div class="divider-line"></div><div class="resource-list">${assignments.filter(a=>a.type==="Worksheet").map((a,i)=>`<div class="resource-row"><div class="file-icon ${i%2?"blue":""}">PDF</div><div class="resource-info"><strong>${a.title}</strong><small>${a.subject} · Due ${a.due}</small><small><span class="status ${a.status==="Submitted"?"black":"pink"}">${a.status}</span></small></div><div class="resource-actions"><button class="btn btn-sm" data-action="download-sheet" data-title="${a.title}">↓ Download</button>${a.status!=="Submitted"?`<button class="btn btn-sm btn-primary" data-action="submit-work" data-title="${a.title}">↑ Submit</button>`:""}</div></div>`).join("")}</div></div></div>`}
function renderTests(){return `${heading("Tests & quizzes","Check your understanding and see how you’re tracking before exam day.")}<div class="dashboard-grid"><div class="section-stack">${panel("Upcoming assessments","Your next opportunities to practise",`<div class="task-list">${[{title:"Physics Topic Quiz",subject:"ATAR Physics",due:"18 Oct 2026",status:"Not started",tone:"pink"},{title:"Chemistry Equilibrium Check-in",subject:"ATAR Chemistry",due:"21 Oct 2026",status:"Opens soon",tone:"blue"},{title:"Methods Mixed Review",subject:"Maths Methods",due:"25 Oct 2026",status:"Scheduled",tone:"pink"}].map(t=>`<div class="task-row"><div class="task-symbol pink">✎</div><div class="task-copy"><strong>${t.title}</strong><small>${t.subject} · ${t.due}</small></div><span class="status ${t.tone}">${t.status}</span><button class="btn btn-sm" data-action="start-quiz" data-title="${t.title}">View</button></div>`).join("")}</div>`)}
 ${panel("Past results","Your recent completed assessments",`<div class="table-wrap"><table><thead><tr><th>Assessment</th><th>Subject</th><th>Score</th><th>Date</th></tr></thead><tbody><tr><td>Mechanics Quiz 02</td><td>Physics</td><td><strong>8/10</strong></td><td>4 Oct</td></tr><tr><td>Equilibrium Check-in</td><td>Chemistry</td><td><strong>17/20</strong></td><td>28 Sep</td></tr><tr><td>Functions Test</td><td>Methods</td><td><strong>14/20</strong></td><td>22 Sep</td></tr></tbody></table></div>`)}</div><div class="section-stack">${panel("Before you start","A few helpful reminders",`<div class="announcement"><div class="task-symbol">✓</div><div><strong>Read the instructions</strong><p>Check the time limit, number of questions, and whether you can retry.</p></div></div><div class="announcement"><div class="task-symbol pink">✦</div><div><strong>Use your revision notes</strong><p>Review the relevant topic before attempting a quiz.</p></div></div>`)}</div></div>`}
function renderProgress(){return `${heading("My progress","A clearer picture of what’s working — and where to focus next.")}<div class="stats-grid">${stat("↗","76%","Overall average","<strong>+8%</strong> vs last month")}${stat("✦","+18%","Best improvement","Chemistry since May","pink")}${stat("✓","8","Tasks completed","This month")}${stat("◎","2","Focus areas","Topics to revisit","pink")}</div><div class="dashboard-grid"><div class="section-stack">${panel("Performance over time","Illustrative subject scores from May to October",`<div class="filter-row"><div>${legend()}</div><select class="chart-period"><option>Last 6 months</option><option>Last 3 months</option></select></div>${chartSvg()}<div class="chart-note"><span class="note-icon">↗</span><span><strong>Keep it consistent.</strong> Your Chemistry results are trending upward. Revisit Physics mechanics questions to strengthen confidence.</span></div>`)}${panel("Subject breakdown","Current progress by subject",subjectCards())}</div><div class="section-stack">${panel("Strengths to build on","Based on your sample assessment data",`<div class="task-row"><div class="task-symbol">✓</div><div class="task-copy"><strong>Chemical Equilibrium</strong><small>Strong recent quiz performance</small></div><span class="status blue">Strong</span></div><div class="task-row"><div class="task-symbol pink">↗</div><div class="task-copy"><strong>Functions & calculus</strong><small>Steady improvement over time</small></div><span class="status blue">Growing</span></div><div class="task-row"><div class="task-symbol pink">◎</div><div class="task-copy"><strong>Mechanics problem solving</strong><small>Worth revisiting this week</small></div><span class="status pink">Focus</span></div>`)}${panel("Next best step","A small action for this week",`<p style="font-size:11px;color:var(--muted);line-height:1.7;margin-top:0">Try 15 minutes of mechanics practice, then review the worked examples in your Physics notes.</p><button class="btn btn-primary" data-page="notes">Open Physics resources →</button>`)}</div></div>`}
function renderSchedule(){return `${heading("Class schedule","Your upcoming ETP learning sessions.")}<div class="panel"><div class="panel-header"><div><div class="panel-title">October 2026</div><div class="panel-subtitle">Demo schedule — confirm actual session times with ETP.</div></div><button class="btn btn-sm" data-action="calendar">＋ Add reminder</button></div><div class="panel-body"><div class="task-list">${[{day:"MON · 12 OCT",time:"4:30 PM – 6:00 PM",title:"Maths Methods",detail:"Functions & calculus · Online session"},{day:"WED · 14 OCT",time:"5:00 PM – 6:30 PM",title:"ATAR Chemistry",detail:"Chemical equilibrium · Online session"},{day:"FRI · 16 OCT",time:"4:30 PM – 6:00 PM",title:"ATAR Physics",detail:"Mechanics revision · Online session"},{day:"SAT · 17 OCT",time:"10:00 AM – 11:30 AM",title:"Maths Applications",detail:"Statistics & networks · Online session"}].map((s,i)=>`<div class="task-row"><div class="date-chip"><strong>${s.day.split(" ")[1]}</strong><small>${s.day.split(" ")[0]}</small></div><div class="task-copy"><strong>${s.title}</strong><small>${s.time} · ${s.detail}</small></div><span class="status ${i%2?"pink":"blue"}">Upcoming</span></div>`).join("")}</div></div></div>`}
function renderAnnouncements(){const list=[["Term 4 revision resources are live","New revision notes and practice sets have been added for Chemistry, Physics, and Maths. Start with the resources marked for your current topics.","9 Oct 2026","blue"],["A reminder about worksheet submissions","Please upload your completed worksheets as a clear PDF or image before the due date. Tutors will add feedback after review.","7 Oct 2026","pink"],["Welcome to your ETP learning space","Use your dashboard to keep track of tasks, find resources, and monitor your progress over time.","1 Oct 2026","blue"]];return `${heading("Announcements","Important updates and reminders from the ETP team.")}<div class="panel"><div class="panel-header"><div><div class="panel-title">Latest updates</div><div class="panel-subtitle">Stay in the loop with what's happening at ETP.</div></div></div><div class="panel-body">${list.map(a=>`<div class="announcement"><div class="task-symbol ${a[3]==="pink"?"pink":""}">◉</div><div><strong>${a[0]}</strong><p>${a[1]}</p><small>${a[2]} · ETP TEAM</small></div></div>`).join("")}</div></div>`}
function renderAccount(){const user=demo[currentRole];return `${heading("Account information","Manage your profile details and account preferences.",`<button class="btn btn-primary" data-action="save-profile">Save changes</button>`)}<div class="profile-grid"><div class="panel"><div class="profile-cover"></div><div class="profile-content"><div class="profile-large"><div class="avatar">${user.initials}</div><div><h2>${user.name}</h2><p>${user.roleLabel} · Elite Tutoring Perth</p></div></div><div class="detail-list"><div class="detail-row"><span>Full name</span><strong>${user.name}</strong></div><div class="detail-row"><span>Email address</span><strong>${user.email}</strong></div><div class="detail-row"><span>Account type</span><strong>${user.roleLabel}</strong></div><div class="detail-row"><span>${currentRole==="student"?"Year level":"Access level"}</span><strong>${user.year}</strong></div><div class="detail-row"><span>Account status</span><strong><span class="status blue">Active</span></strong></div></div></div></div><div class="section-stack">${panel("Personal details","These fields are sample data for the prototype.",`<form class="form-grid" id="profileForm"><div class="field full"><label>Display name</label><input value="${user.name}"></div><div class="field full"><label>Email address</label><input type="email" value="${user.email}"></div><div class="field"><label>Year level</label><select><option>${user.year}</option><option>Year 11 ATAR</option><option>Year 12 ATAR</option></select></div><div class="field"><label>Time zone</label><select><option>Perth (AWST)</option></select></div><div class="field full"><label>Study goal</label><textarea>Build consistency, strengthen exam technique, and feel confident going into ATAR exams.</textarea></div></form>`)}${panel("Account security","Keep your demo account secure.",`<div class="setting-row"><div><strong>Password</strong><small>Change your password regularly.</small></div><button class="btn btn-sm" data-action="change-password">Change</button></div><div class="setting-row"><div><strong>Two-factor authentication</strong><small>Additional account protection (not active in this prototype).</small></div><button class="toggle" data-toggle></button></div>`)}</div></div>`}
function renderSettings(){return `${heading("Settings","Make your learning space work for you.")}<div class="profile-grid"><div class="section-stack">${panel("Notifications","Choose what you’d like to be reminded about.",`<div class="setting-row"><div><strong>Assignment reminders</strong><small>Receive reminders before worksheets are due.</small></div><button class="toggle on" data-toggle></button></div><div class="setting-row"><div><strong>New resources</strong><small>Know when your tutor shares new notes.</small></div><button class="toggle on" data-toggle></button></div><div class="setting-row"><div><strong>Test and quiz updates</strong><small>Get notified about upcoming assessments.</small></div><button class="toggle on" data-toggle></button></div><div class="setting-row"><div><strong>Progress summaries</strong><small>Receive periodic summaries of your performance.</small></div><button class="toggle" data-toggle></button></div>`)}${panel("Appearance","Simple, accessible, and easy to use.",`<div class="setting-row"><div><strong>Reduced motion</strong><small>Reduce decorative interface animations.</small></div><button class="toggle" data-toggle></button></div><div class="setting-row"><div><strong>Compact layout</strong><small>Fit more information on the screen.</small></div><button class="toggle" data-toggle></button></div>`)}</div><div class="section-stack">${panel("Your account","Your details and security.",`<div class="setting-row"><div><strong>Profile information</strong><small>Review your name, email, and year level.</small></div><button class="btn btn-sm" data-page="account">Manage</button></div><div class="setting-row"><div><strong>Sign out</strong><small>Finish your current session on this device.</small></div><button class="btn btn-sm" id="settingsLogout">Log out</button></div>`)}${panel("Privacy & support","Need help with your account?",`<p style="font-size:11px;line-height:1.7;color:var(--muted);margin-top:0">For account access, student data, or learning support questions, contact the ETP team directly. This demo does not store your settings on a server.</p><a class="btn" href="https://www.elitetutoringperth.com.au/" target="_blank" rel="noreferrer">Visit ETP website ↗</a>`)}</div></div>`}
function renderStudents(){return `${heading("Students","Manage student access, year levels, and enrolments.",`<button class="btn btn-primary" data-action="add-student">＋ Add student</button>`)}<div class="stats-grid">${stat("♙","48","Total students","Across 6 batches")}${stat("✓","45","Active accounts","Ready to learn","pink")}${stat("◷","2","Pending enrolments","Need class assignment")}${stat("◎","4","Year 11 batches","Year 12 included","pink")}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Student directory</div><div class="panel-subtitle">Sample records for demonstrating admin workflows.</div></div></div><div class="panel-body"><div class="filter-row"><input class="search-input" id="studentSearch" placeholder="Search students…"><div class="filter-group"><select class="select-input"><option>All year levels</option><option>Year 11</option><option>Year 12</option></select><select class="select-input"><option>All statuses</option><option>Active</option><option>Pending</option></select></div></div><div id="studentsTable">${studentTable(students)}</div></div></div>`}
