function renderAssign(){return `${heading("Assign work","Share a worksheet, notes, or assessment with a class or selected students.")}<div class="profile-grid"><div class="panel"><div class="panel-header"><div><div class="panel-title">Create an assignment</div><div class="panel-subtitle">Complete the details below to preview a new assignment.</div></div></div><div class="panel-body"><form id="assignForm" class="form-grid"><div class="field full"><label>Assignment title *</label><input name="title" placeholder="e.g. Chemical Equilibrium Worksheet" required></div><div class="field"><label>Subject *</label><select name="subject" required><option value="">Choose subject</option>${subjects.map(s=>`<option>${s.name}</option>`).join("")}</select></div><div class="field"><label>Work type</label><select name="type"><option>Worksheet</option><option>Notes</option><option>Test</option><option>Quiz</option></select></div><div class="field"><label>Assign to *</label><select name="batch" required><option value="">Choose class or batch</option><option>Year 12 · Chemistry</option><option>Year 12 · Physics</option><option>Year 12 · Maths Methods</option><option>Year 11 · Applications</option><option>Selected students</option></select></div><div class="field"><label>Due date</label><input name="due" type="date" value="2026-10-18"></div><div class="field full"><label>Instructions</label><textarea name="instructions" placeholder="Add submission instructions, topic details, or marking guidance…"></textarea></div><div class="field full"><label>Attach a file (demo only)</label><input name="file" type="file" accept=".pdf,.doc,.docx,.png,.jpg"><small style="font-size:9px;color:var(--muted)">The file picker is visual only; files are not uploaded or stored.</small></div><div class="field full"><label><input type="checkbox" name="publish" checked style="width:auto;margin-right:6px;accent-color:var(--blue)"> Publish assignment immediately</label></div><div class="field full"><button class="btn btn-primary" type="submit">Create assignment <span>→</span></button></div></form></div></div><div class="section-stack">${panel("Before publishing","A quick checklist",`<div class="task-row"><div class="task-symbol">✓</div><div class="task-copy"><strong>Check the target batch</strong><small>Only selected students should see the assignment.</small></div></div><div class="task-row"><div class="task-symbol pink">✓</div><div class="task-copy"><strong>Set a clear deadline</strong><small>Give students enough time to complete the work.</small></div></div><div class="task-row"><div class="task-symbol">✓</div><div class="task-copy"><strong>Attach the right file</strong><small>For the real portal, confirm the file uploaded successfully.</small></div></div>`)}${panel("Recent assignments","Latest work shared",taskRows(assignments.slice(0,3)))}</div></div>`}
function renderSubmissions(){return `${heading("Submissions","Review student answers, provide feedback, and download answer sheets.",`<button class="btn" data-action="download-submissions">↓ Export list</button>`)}<div class="stats-grid">${stat("☷","12","To review","5 received today","pink")}${stat("✓","28","Reviewed this week","Across all subjects")}${stat("◷","1.8 days","Average review time","Target: under 2 days","pink")}${stat("▤","4","Answer sheets","Available for download")}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Student submissions</div><div class="panel-subtitle">Open a submission to review the file, add marks, and leave feedback.</div></div></div><div class="panel-body"><div class="filter-row"><input class="search-input" id="submissionSearch" placeholder="Search by student or assignment…"><div class="filter-group"><select class="select-input"><option>All statuses</option><option>Awaiting review</option><option>Reviewed</option></select><select class="select-input"><option>All subjects</option>${subjects.map(s=>`<option>${s.name}</option>`).join("")}</select></div></div><div id="submissionTable">${submissionTable(submissions)}</div><div class="divider-line"></div><div class="panel-title" style="margin:18px 0 5px">Answer sheets & marking guides</div><div class="panel-subtitle">Sample download actions — demo files are generated locally.</div><div class="resource-list">${["Chemical Equilibrium — Marking Guide","Differentiation — Worked Solutions","Circular Motion — Answer Sheet"].map((t,i)=>`<div class="resource-row"><div class="file-icon ${i%2?"blue":""}">PDF</div><div class="resource-info"><strong>${t}</strong><small>${["ATAR Chemistry","Maths Methods","ATAR Physics"][i]} · Answer sheet</small></div><button class="btn btn-sm" data-action="download-answer" data-title="${t}">↓ Download</button></div>`).join("")}</div></div></div>`}
function renderAdminTests(){return `${heading("Tests & quizzes","Create assessments, schedule them for a batch, and review results.",`<button class="btn btn-primary" data-action="create-test">＋ Create test</button>`)}<div class="stats-grid">${stat("✎","8","Published assessments","Across 4 subjects")}${stat("◷","3","Scheduled this week","Upcoming tests","pink")}${stat("✓","82%","Average completion","For recent quizzes")}${stat("◎","4","Question sets","Ready to assign","pink")}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Assessment library</div><div class="panel-subtitle">Sample assessments and their current status.</div></div></div><div class="panel-body"><div class="table-wrap"><table><thead><tr><th>Assessment</th><th>Subject</th><th>Assigned to</th><th>Due date</th><th>Status</th><th>Actions</th></tr></thead><tbody>${[["Physics Topic Quiz","ATAR Physics","Year 12 · Physics","18 Oct 2026","Scheduled"],["Equilibrium Check-in","ATAR Chemistry","Year 12 · Chemistry","21 Oct 2026","Published"],["Methods Mixed Review","Maths Methods","Year 12 · Methods","25 Oct 2026","Draft"],["Statistics Practice Test","Maths Applications","Year 11 · Applications","30 Oct 2026","Published"]].map((r,i)=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td><span class="status ${i===2?"black":i%2?"blue":"pink"}">${r[4]}</span></td><td><button class="link-btn" data-action="edit-test" data-title="${r[0]}">Manage</button></td></tr>`).join("")}</tbody></table></div></div></div>`}
function renderAdminProgress(){return `${heading("Student progress","Monitor trends, spot opportunities to support students, and export reports.")}<div class="stats-grid">${stat("↗","76%","Cohort average","<strong>+6%</strong> this term")}${stat("✦","18","Improving students","Over the last 6 weeks","pink")}${stat("◎","7","Students to check in","Based on sample data")}${stat("✓","84%","Task completion","Across active batches","pink")}</div><div class="dashboard-grid"><div class="section-stack">${panel("Cohort performance","Illustrative performance trends by subject",`<div class="filter-row"><div>${legend()}</div><select class="chart-period"><option>Last 6 months</option></select></div>${chartSvg()}`)}${panel("Student list","Sample performance summary",`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Subject</th><th>Average</th><th>Trend</th></tr></thead><tbody>${[["Alex Carter","Methods","78%","Improving"],["Olivia Chen","Chemistry","86%","Improving"],["Noah Williams","Physics","64%","Review"],["Mia Thompson","Chemistry","72%","Stable"]].map((r,i)=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td><strong>${r[2]}</strong></td><td><span class="status ${i===2?"pink":"blue"}">${r[3]}</span></td></tr>`).join("")}</tbody></table></div>`)}</div><div class="section-stack">${panel("Suggested follow-ups","Sample insights — not automated diagnosis",`<div class="task-row"><div class="task-symbol pink">◎</div><div class="task-copy"><strong>Noah Williams · Physics</strong><small>Review recent mechanics assessment results.</small></div><button class="link-btn" data-action="student-report" data-student="Noah Williams">View</button></div><div class="task-row"><div class="task-symbol">↗</div><div class="task-copy"><strong>Year 12 Chemistry</strong><small>Recent cohort average is trending upward.</small></div></div><div class="task-row"><div class="task-symbol pink">▤</div><div class="task-copy"><strong>Export progress report</strong><small>Download a sample summary for review.</small></div><button class="link-btn" data-action="export-progress">Export</button></div>`)}${panel("Reporting note","Prototype data",`<p style="font-size:10px;color:var(--muted);line-height:1.7;margin:0">All student scores, trends, and recommendations on this screen are sample values created to demonstrate the proposed experience. Real reports must use verified assessment data.</p>`)}</div></div>`}
function renderAdminAnnouncements(){return `${heading("Announcements","Share important updates with students and teaching batches.",`<button class="btn btn-primary" data-action="new-announcement">＋ New announcement</button>`)}<div class="profile-grid"><div class="panel"><div class="panel-header"><div><div class="panel-title">Publish an update</div><div class="panel-subtitle">Draft a message and choose who should see it.</div></div></div><div class="panel-body"><form id="announcementForm" class="form-grid"><div class="field full"><label>Announcement title *</label><input name="title" required placeholder="e.g. Term 4 revision resources are live"></div><div class="field full"><label>Message *</label><textarea name="message" required placeholder="Write a clear update for students…"></textarea></div><div class="field"><label>Audience</label><select name="audience"><option>All students</option><option>Year 11 batches</option><option>Year 12 batches</option><option>Selected subject</option></select></div><div class="field"><label>Publish date</label><input type="date" value="2026-10-10"></div><div class="field full"><button class="btn btn-primary" type="submit">Publish announcement →</button></div></form></div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">Recent announcements</div><div class="panel-subtitle">Updates currently visible in the demo.</div></div></div><div class="panel-body">${renderAnnouncementList()}</div></div></div>`}
function renderAnnouncementList(){return `<div class="announcement"><div class="task-symbol">◉</div><div><strong>Term 4 revision resources are live</strong><p>New revision notes and practice sets are available.</p><small>Published · 9 Oct 2026</small></div></div><div class="announcement"><div class="task-symbol pink">◉</div><div><strong>Worksheet submission reminder</strong><p>Upload completed work before the deadline.</p><small>Published · 7 Oct 2026</small></div></div>`}
function renderAdminSettings(){return `${heading("Portal settings","Manage demo portal preferences and administrative defaults.")}<div class="profile-grid"><div class="section-stack">${panel("General settings","Prototype configuration",`<div class="setting-row"><div><strong>Portal name</strong><small>Elite Tutoring Perth Learning Portal</small></div><button class="btn btn-sm" data-action="edit-portal-name">Edit</button></div><div class="setting-row"><div><strong>Default time zone</strong><small>Australian Western Standard Time (AWST)</small></div><button class="btn btn-sm" data-action="edit-timezone">Edit</button></div><div class="setting-row"><div><strong>Student self-enrolment</strong><small>Require admin approval before students access a batch.</small></div><button class="toggle on" data-toggle></button></div><div class="setting-row"><div><strong>Allow late submissions</strong><small>Tutors can decide whether to accept work after the deadline.</small></div><button class="toggle on" data-toggle></button></div>`)}${panel("Security checklist","Before this concept becomes a real portal",`<div class="task-row"><div class="task-symbol">✓</div><div class="task-copy"><strong>Role-based access</strong><small>Enforce permissions on the server and database.</small></div><span class="status pink">To implement</span></div><div class="task-row"><div class="task-symbol pink">✓</div><div class="task-copy"><strong>Secure file storage</strong><small>Protect student submissions and answer sheets.</small></div><span class="status pink">To implement</span></div><div class="task-row"><div class="task-symbol">✓</div><div class="task-copy"><strong>Backups & monitoring</strong><small>Set up recovery and production error alerts.</small></div><span class="status pink">To implement</span></div>`)}</div><div class="section-stack">${panel("Data & privacy","Student information needs careful handling",`<p style="font-size:11px;color:var(--muted);line-height:1.7;margin-top:0">This is a front-end prototype only. It does not store student data on a server. Before production, ETP should confirm its privacy policy, consent process, data retention, and access requirements.</p><button class="btn" data-action="privacy-checklist">View launch checklist</button>`)}${panel("Demo environment","Sample data only",`<div class="detail-row"><span>Build type</span><strong>Front-end wireframe</strong></div><div class="detail-row"><span>Backend connection</span><strong>Not connected</strong></div><div class="detail-row"><span>Sample accounts</span><strong>2 roles</strong></div><div class="detail-row"><span>Persistent storage</span><strong>None</strong></div>`)}</div></div>`}
function renderPage(){
 $("#breadcrumbCurrent").textContent=pageNames[currentPage]||"Overview";
 let html="";
 if(currentRole==="student"){
  const map={overview:renderStudentOverview,subjects:renderSubjects,notes:renderNotes,worksheets:renderWorksheets,tests:renderTests,progress:renderProgress,schedule:renderSchedule,announcements:renderAnnouncements,account:renderAccount,settings:renderSettings};
  html=(map[currentPage]||renderStudentOverview)();
 }else{
  const map={overview:renderAdminOverview,students:renderStudents,classes:renderClasses,resources:renderResources,assign:renderAssign,submissions:renderSubmissions,tests:renderAdminTests,progress:renderAdminProgress,announcements:renderAdminAnnouncements,account:renderAccount,settings:renderAdminSettings};
  html=(map[currentPage]||renderAdminOverview)();
 }
 $("#pageContent").innerHTML=html;
 bindPageInteractions();
}
function bindPageInteractions(){
 const search=$("#resourceSearch"),subject=$("#resourceSubject");
 if(search)search.addEventListener("input",filterResources);
 if(subject)subject.addEventListener("change",filterResources);
 const ss=$("#studentSearch");if(ss)ss.addEventListener("input",()=>{$("#studentsTable").innerHTML=studentTable(students.filter(s=>(s.name+" "+s.email+" "+s.subjects).toLowerCase().includes(ss.value.toLowerCase())))});
 const sub=$("#submissionSearch");if(sub)sub.addEventListener("input",()=>{$("#submissionTable").innerHTML=submissionTable(submissions.filter(s=>(s.student+" "+s.work+" "+s.subject).toLowerCase().includes(sub.value.toLowerCase())))});
 const af=$("#assignForm");if(af)af.addEventListener("submit",e=>{e.preventDefault();const data=new FormData(af);showToast(`Demo assignment “${data.get("title")}” created locally. No data was saved.`);af.reset()});
 const ann=$("#announcementForm");if(ann)ann.addEventListener("submit",e=>{e.preventDefault();showToast("Demo announcement published locally. No data was saved.");ann.reset()});
 const pf=$("#profileForm");if(pf)pf.addEventListener("submit",e=>e.preventDefault());
 const settingsLogout=$("#settingsLogout");if(settingsLogout)settingsLogout.addEventListener("click",logout);
}
function filterResources(){const q=($("#resourceSearch")?.value||"").toLowerCase(),s=$("#resourceSubject")?.value||"";const list=resources.filter(r=>(r.title+" "+r.subject).toLowerCase().includes(q)&&(!s||r.subject===s));const target=$("#resourceRows");if(target)target.innerHTML=list.length?resourceRows(list):`<div class="empty-state"><div class="empty-icon">⌕</div><h3>No resources found</h3><p>Try another search or select a different subject.</p></div>`}
function downloadText(title,content){const blob=new Blob([content],{type:"text/plain;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=title.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")+".txt";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function handleAction(el){
 const action=el.dataset.action,title=el.dataset.title||"Sample learning resource";
 if(action==="subject"){showToast(`${el.dataset.subject}: subject detail view is represented by the subject card.`)}
 else if(action==="download-sheet"||action==="download-answer"){downloadText(title,`${title}\n\nELITE TUTORING PERTH — DEMO FILE\n\nThis is a sample placeholder generated by the front-end wireframe. Replace it with the real PDF or marking guide in the production portal.\n\nNo student data is included.`);showToast("Sample file downloaded.")}
 else if(action==="submit-work"){showToast(`Submission flow preview for “${title}”. A real portal would open a secure file upload.`)}
 else if(action==="start-quiz"){showToast(`Preview: ${title}. Quiz attempt and scoring are not connected in this wireframe.`)}
 else if(action==="review"){showToast(`Opening sample submission for ${el.dataset.student}. Marking and feedback are demo-only.`)}
 else if(action==="upload-resource"){showToast("Upload panel preview: real file storage will be connected in the production build.")}
 else if(action==="add-student"){showToast("Add student form preview. Production version will create a secure student account.")}
 else if(action==="edit-student"){showToast(`Manage student preview: ${el.dataset.student}.`)}
 else if(action==="create-batch"||action==="manage-batch"){showToast(action==="create-batch"?"Create batch form preview.":`Batch management preview: ${title}.`)}
 else if(action==="create-test"||action==="edit-test"){showToast(`${action==="create-test"?"Create test":"Edit test"} preview. Real assessment publishing will be connected later.`)}
 else if(action==="download-submissions"){downloadText("etp-submission-export","Student,Assignment,Subject,Status\n"+submissions.map(s=>`${s.student},${s.work},${s.subject},${s.status}`).join("\n"));showToast("Sample submission list exported.")}
 else if(action==="export-progress"){downloadText("etp-progress-summary","ELITE TUTORING PERTH — SAMPLE PROGRESS SUMMARY\n\nCohort average: 76%\nImproving students: 18\nTask completion: 84%\n\nIllustrative demo data only.");showToast("Sample progress summary exported.")}
 else if(action==="student-report"){showToast(`Sample progress report for ${el.dataset.student}.`)}
 else if(action==="new-announcement"){document.querySelector("#announcementForm")?.scrollIntoView({behavior:"smooth",block:"center"})}
 else if(action==="calendar"){showToast("Reminder preview: calendar integration is not connected.")}
 else if(action==="save-profile"){showToast("Profile changes are a visual preview and are not saved.")}
 else if(action==="change-password"){showToast("Password management will use the secure authentication service in production.")}
 else if(action==="edit-portal-name"||action==="edit-timezone"){showToast("Settings editor preview.")}
 else if(action==="privacy-checklist"){showToast("Launch checklist: access controls, privacy policy, consent, retention, backups, monitoring, and testing.")}
 else if(action==="filter-resources"){ $("#resourceSearch")?.focus(); }
}
document.addEventListener("click",e=>{
 const page=e.target.closest("[data-page]");if(page){e.preventDefault();goPage(page.dataset.page);return}
 const action=e.target.closest("[data-action]");if(action){handleAction(action);return}
 const dl=e.target.closest("[data-download]");if(dl){const r=resources[Number(dl.dataset.download)]||resources[0];downloadText(r.title,`${r.title}\n\nELITE TUTORING PERTH — SAMPLE RESOURCE\n\nThis placeholder demonstrates the download interaction. In production, the button will download the tutor-uploaded file.`);showToast("Sample resource downloaded.");return}
 const toggle=e.target.closest("[data-toggle]");if(toggle){toggle.classList.toggle("on");showToast("Preference toggled for this preview.");return}
 if(e.target.closest("[data-dismiss]")){e.target.closest(".notice-banner").remove();return}
});
$$(".role-option").forEach(b=>b.addEventListener("click",()=>setRole(b.dataset.role)));
$("#loginForm").addEventListener("submit",e=>{e.preventDefault();login()});
$("#togglePassword").addEventListener("click",()=>{const p=$("#password");p.type=p.type==="password"?"text":"password";$("#togglePassword").textContent=p.type==="password"?"Show":"Hide"});
$("#forgotBtn").addEventListener("click",()=>showToast("Password reset is a demo interaction. Real reset emails require backend authentication."));
$("#toggleDemo").addEventListener("click",()=>{$("#demoDetails").classList.toggle("hidden");$("#toggleDemo").textContent=$("#demoDetails").classList.contains("hidden")?"⌄":"⌃"});
$$("[data-fill]").forEach(b=>b.addEventListener("click",()=>setRole(b.dataset.fill)));
$("#logoutBtn").addEventListener("click",logout);
$("#mobileMenu").addEventListener("click",()=>{$("#sidebar").classList.add("open");$("#mobileOverlay").classList.add("show")});
$("#mobileOverlay").addEventListener("click",()=>{$("#sidebar").classList.remove("open");$("#mobileOverlay").classList.remove("show")});
$("#notificationBtn").addEventListener("click",()=>goPage("announcements"));
setRole("student");